import { Database } from "bun:sqlite";
const db = new Database("/data00/home/zhangpeng.pada/.trellis/data.db", { readonly: true });
const SID = "37f1e158-bfe2-4564-b49a-45767900d964";

// 1. server-side: load + parse all nodes (what getSessionNodes does)
let t = performance.now();
const rows = db.prepare("SELECT * FROM nodes WHERE session_id = ? ORDER BY created_at").all(SID) as any[];
const tFetch = performance.now() - t;

t = performance.now();
let totalParsed = 0;
const parsed = rows.map((r) => {
  let tc: any[] = [];
  if (r.tool_calls_json) { try { const p = JSON.parse(r.tool_calls_json); if (Array.isArray(p)) tc = p; } catch {} }
  totalParsed += r.tool_calls_json?.length ?? 0;
  return { ...r, toolCalls: tc, tool_calls_json: undefined };
});
const tParse = performance.now() - t;

// 2. serialize to API response
t = performance.now();
const body = JSON.stringify({ session: {}, nodes: parsed, notes: [] });
const tStringify = performance.now() - t;

// 3. client-side re-parse
t = performance.now();
const reparsed = JSON.parse(body);
const tReparse = performance.now() - t;

// 4. buildToolTree cost (import from repo)
const { buildToolTree, countToolTree } = await import("/data00/home/zhangpeng.pada/trellis/lib/tool-tree.ts");
t = performance.now();
let totalCalls = 0;
for (const n of reparsed.nodes) {
  if (n.toolCalls?.length) {
    const tree = buildToolTree(n.toolCalls);
    totalCalls += countToolTree(tree).total;
  }
}
const tTree = performance.now() - t;

console.log(JSON.stringify({
  nodes: rows.length,
  toolCallsJsonMB: (totalParsed / 1048576).toFixed(1),
  responseMB: (body.length / 1048576).toFixed(1),
  totalToolCalls: totalCalls,
  ms: { sqlFetch: +tFetch.toFixed(0), serverJsonParse: +tParse.toFixed(0), stringify: +tStringify.toFixed(0), clientJsonParse: +tReparse.toFixed(0), buildToolTreeAll: +tTree.toFixed(0) },
}, null, 2));
EOF
