// 流式期间只做最小 rehype：rehypeRaw 跳过（半行 HTML 标签既浪费又可能抛错），
// rehypeHighlight 也跳过——它会在每一帧对**整段** response 重跑语法高亮，
// 几百 KB 的长回复能把主线程卡死，正是「tab 点不开」的主因。高亮只在 done
// 态跑一次；流式态只保留数学公式渲染。

// #7: the single "turn" reading/interaction surface, shared by every place a
// node is read in full (the linear thread is the only consumer today — the
// old NodeFullView duplicated all of this and has been retired). Carries the
// complete capability set: parent-anchor jump banner, editable question,
// tool-call panel, mark-injected markdown body with live streaming, the
// action row (CLI resume / regenerate / card image / copy), generated files,
// and the paused-interaction form.
// React.memo：线性 thread 订阅整个 `nodes` 对象，流式期间每个 tool_call
// 事件（合批后仍是每帧一次）都会让父组件重渲。未变的节点（同引用）直接跳
// 过——避免 15 张已完成卡片每次都重跑完整语法高亮。只有正在流式
// 的节点引用每帧更新，正常重渲（且流式态已不跑高亮，成本低）。
export const TurnCard = memo(function TurnCard({ node }: { node: ChatNode }) {
  const jumpToParentAtAnchor = useSessionStore((s) => s.jumpToParentAtAnchor);
  const hasParent = useSessionStore((s) =>
    Boolean(node.parentId && s.nodes[node.parentId]),
  );

  if (node.kind === "reference") {
    return <ReferenceFullBody key={node.id} node={node} />;
  }

  return (
    <>
      {node.parentAnchor && hasParent && (
        <button
          onClick={() => jumpToParentAtAnchor(node.parentId!, node.id)}
          className="w-full text-left mb-3 px-3 py-2 rounded-lg bg-fork-muted border border-fork-line text-ui text-fork-ink active:scale-[0.99] transition-transform shadow-raise hover:bg-fork-line/25"
          title="回到父节点的引用处 (B)"
        >
          <span className="text-fork mr-1">↳</span>
          从「
          <span className="font-medium">
            {truncate(node.parentAnchor.selectedText, 60)}
          </span>
          」分叉
          <span className="ml-1.5 text-fork-ink/70">
            · 点击或按
            <kbd className="mx-1 px-1 py-px rounded bg-fork-line/40 border border-fork-line font-mono text-nano">
              B
            </kbd>
            回到引用处
          </span>
        </button>
      )}
      <QuestionBlock
        nodeId={node.id}
        question={node.question}
        attachments={node.attachments}
      />
      {/* One chronological timeline of everything the turn did — delegated
          work nests under the call that spawned it rather than being pulled
          out into a parallel panel. */}
      <ToolTimeline
        toolCalls={node.toolCalls}
        live={node.status === "streaming"}
      />
      {/* key={node.id} forces a fresh ResponseBody fiber per node: the
          imperative <mark> injection inside react-markdown's output diverges
          from React's virtual tree, so when the node prop changes in-place
          React's reconciler tries to removeChild against DOM that was
          re-parented under our marks and throws NotFoundError. Unmounting
          cleanly lets the cleanup clearMarks() run before React touches the
          DOM. */}
      <ResponseBody key={node.id} node={node} />
      {/* A路③: when this node's run is paused on an interactive tool, render
          the answer form below the response so the user can reply in place
          and the model continues. */}
      {node.pendingInteraction && (
        <InteractionForm
          nodeId={node.id}
          interaction={node.pendingInteraction}
        />
      )}
    </>
  );
});

// D5: regenerate the same question as a NEW sibling (a second "version"),
// rather than overwriting in place like retry. The branch entries in the
// thread then let the user compare the variants side by side.
function RegenerateVariantButton({
  nodeId,
  question,
}: {
  nodeId: string;
  question: string;
}) {
  const editNode = useSessionStore((s) => s.editNode);
  return (
    <Button
      type="button"
      variant="secondary"
      size="sm"
      onClick={(e) => {
        e.stopPropagation();
        editNode(nodeId, question);
      }}
      title="用相同问题再生成一个版本（新建兄弟节点，可在分支列表对比）"
      className="nodrag"
    >
      ↻ 再答一版
    </Button>
  );
}

function QuestionBlock({
  nodeId,
  question,
  attachments,
}: {
  nodeId: string;
  question: string;
  attachments: NodeAttachment[];
}) {
  const editNode = useSessionStore((s) => s.editNode);
  const sendKey = useSessionStore((s) => s.sendKey);
  const [editing, setEditing] = useState(false);
  const [text, setText] = useState(question);

  const submit = () => {
    const t = text.trim();
    if (!t) return;
    setEditing(false);
    editNode(nodeId, t);
  };
  const cancel = () => {
    setEditing(false);
    setText(question);
  };

  if (editing) {
    return (
      <div className="bg-accent-muted border border-accent-line rounded-lg px-4 py-3 mb-4">
        <textarea
          value={text}
          autoFocus
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => {
            if (isSendCombo(e, sendKey)) {
              e.preventDefault();
              submit();
            } else if (e.key === "Escape") {
              e.preventDefault();
              cancel();
            }
          }}
          rows={3}
          className="w-full resize-none px-3 py-2 rounded-field border border-accent-line bg-surface text-reading text-ink-strong outline-none focus:border-accent leading-relaxed"
        />
        <div className="flex items-center justify-between gap-2 mt-2">
          <span className="text-label text-ink-faint min-w-0 truncate">
            改问法会新建一个分支，保留原问答（{sendHint(sendKey)}）
          </span>
          <div className="flex items-center gap-2 shrink-0">
            <Button variant="ghost" size="sm" onClick={cancel}>
              取消
            </Button>
            <Button
              variant="primary"
              size="sm"
              onClick={submit}
              disabled={!text.trim()}
            >
              ↻ 重问
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="group bg-accent-muted border-l-[3px] border-l-accent rounded-lg px-4 py-3 mb-5 flex items-start gap-3">
      <div className="w-7 h-7 rounded-full bg-accent text-ink-inverse text-label flex items-center justify-center shrink-0 font-medium shadow-raise">
        你
      </div>
      <div className="flex-1 text-reading text-ink leading-relaxed pt-1 font-medium whitespace-pre-wrap break-words min-w-0">
        {question}
        {attachments.length > 0 && (
          <div className="mt-2 font-normal">
            <AttachmentPreview attachments={attachments} readOnly />
          </div>
        )}
      </div>
      <button
        onClick={() => {
          setText(question);
          setEditing(true);
        }}
        title="编辑问题（会新建一个分支重问）"
        aria-label="编辑问题"
        className="shrink-0 mt-0.5 w-7 h-7 flex items-center justify-center rounded-md text-ink-muted opacity-60 sm:opacity-0 group-hover:opacity-100 hover:bg-surface-raised hover:text-accent transition-opacity"
      >
        <svg
          width="14"
          height="14"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden
        >
          <path d="M12 20h9" />
          <path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z" />
        </svg>
      </button>
    </div>
  );
}

// Dim auto-scrolling viewport for the live thinking stream. Pinned to the
// bottom as text grows (thinking is transient status, not reading material —
// following the tail beats preserving scroll position).
function ThinkingScroll({
  text,
  className,
}: {
  text: string;
  className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = ref.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [text]);
  return (
    <div
      ref={ref}
      className={`max-h-36 overflow-y-auto whitespace-pre-wrap break-words text-ui leading-relaxed text-ink-faint ${className ?? ""}`}
    >
      {text}
    </div>
  );
}

// S88：@提及的一次性外援标记。刻意只说「由 @提及的 Agent 作答」而不查名字 ——
// 节点只存 agent id，为一枚 chip 去 fetch 每个节点的 agent 名不值当，而且被删掉的
// agent 会让历史节点渲染出一片空白。语义（这轮不是主线人格答的）已经传达到了。
function MentionChip() {
  return (
    <div className="mb-2 inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-accent-muted text-accent-ink text-label">
      <span aria-hidden>🎭</span>
      <span>这一轮由 @提及的 Agent 单独作答（主线人格不变）</span>
    </div>
  );
}

function ResponseBody({ node }: { node: ChatNode }) {
  const retryNode = useSessionStore((s) => s.retryNode);
  const bodyRef = useRef<HTMLDivElement>(null);
  const isStreaming = node.status === "streaming";
  const isError = node.status === "error";
  // 错误降级（见 SupersededErrorNotice）：有子节点 = 用户已续跑/绕过，
  // 红横幅降级为安静备注。boolean selector，仅在真假翻转时触发重渲染。
  const hasChildren = useSessionStore((s) => {
    for (const k in s.nodes) {
      if (s.nodes[k].parentId === node.id) return true;
    }
    return false;
  });
  // P1: 视口外的 done 卡片先挂纯文本占位，滚到 800px 内再升级完整
  // markdown（useNearViewport），长会话首次切换也不必等全部卡片跑完
  // parse+highlight+katex。锚点跳转目标强制立即渲染——marks 的滚动闪烁
  // 依赖 markdown DOM。
  const isAnchorTarget = useSessionStore(
    (s) => s.pendingScrollAnchor?.nodeId === node.id,
  );
  const near = useNearViewport(bodyRef, { force: isAnchorTarget });

  const { onMarkClick } = useMarkdownBodyMarks({
    bodyRef,
    nodeId: node.id,
    contentVersion: node.response,
    suspended: isStreaming || !near,
  });

  // A1: live markdown render while streaming. Accumulate deltas in a ref and
  // flush to state on requestAnimationFrame (coalescing token bursts to one
  // re-render per frame), then render through ReactMarkdown so code/lists/
  // tables format as they arrive — matching GPT/Claude. Affordable here
  // because turn cards live in a plain scroll list, not inside the ReactFlow
  // canvas (ChatNode deliberately keeps the textContent-direct sink there).
  const [liveText, setLiveText] = useState("");
  useEffect(() => {
    if (!isStreaming) return;
    let raf = 0;
    let buf = node.response + getStreamPending(node.id);
    setLiveText(buf);
    const flush = () => {
      raf = 0;
      setLiveText(buf);
    };
    const unsub = subscribeStream(node.id, (delta) => {
      buf += delta;
      if (!raf) raf = requestAnimationFrame(flush);
    });
    return () => {
      if (raf) cancelAnimationFrame(raf);
      unsub();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isStreaming, node.id]);

  // Extended thinking: claude streams a thinking block BEFORE the text block
  // (minutes under high effort). Same rAF-coalesced bus subscription as the
  // text deltas, separate channel. Ephemeral — vanishes when the turn ends.
  const [liveThinking, setLiveThinking] = useState("");
  useEffect(() => {
    if (!isStreaming) {
      setLiveThinking("");
      return;
    }
    let raf = 0;
    let buf = getStreamPending(thinkingChannel(node.id));
    setLiveThinking(buf);
    const flush = () => {
      raf = 0;
      setLiveThinking(buf);
    };
    const unsub = subscribeStream(thinkingChannel(node.id), (delta) => {
      buf += delta;
      if (!raf) raf = requestAnimationFrame(flush);
    });
    return () => {
      if (raf) cancelAnimationFrame(raf);
      unsub();
    };
  }, [isStreaming, node.id]);

  return (
    <div
      ref={bodyRef}
      data-chat-node-id={node.id}
      onClick={onMarkClick}
      className="md-body text-reading text-ink leading-relaxed"
    >
      {/* S88 @提及：这一轮是外援答的，标出来 —— 否则读者会以为主线人格变了。
          会话级人设（agentScope==='session'）刻意不挂 chip：每张卡都挂一枚是
          噪音，那个显示在 Header 的 ModeBadge 上。 */}
      {node.agentScope === "mention" && <MentionChip />}
      {isStreaming && liveThinking && (
        // The思考期 surface. While no answer text yet: an open dim panel with
        // the thinking stream (this is what used to look like a dead UI for
        // up to minutes). Once the answer starts: collapse to a <details>
        // (uncontrolled so a user toggle sticks). Gone entirely at done.
        liveText ? (
          <details className="mb-2">
            <summary className="cursor-pointer select-none text-ui text-ink-faint hover:text-ink-muted">
              🧠 思考过程（{liveThinking.length} 字）
            </summary>
            <ThinkingScroll text={liveThinking} className="mt-1" />
          </details>
        ) : (
          <div className="mb-2 rounded-md border border-line/70 bg-surface-muted/60 px-3 py-2">
            <div className="mb-1 flex items-center gap-1.5 text-ui text-ink-faint">
              <span className="w-1.5 h-1.5 rounded-full bg-accent animate-pulse" />
              思考中…
            </div>
            <ThinkingScroll text={liveThinking} />
          </div>
        )
      )}
      {isStreaming ? (
        liveText ? (
          <>
            <ReactMarkdown
              remarkPlugins={MARKDOWN_REMARK_PLUGINS}
              rehypePlugins={MARKDOWN_STREAMING_REHYPE_PLUGINS}
              components={MD_COMPONENTS}
            urlTransform={MD_URL_TRANSFORM}
            >
              {liveText}
            </ReactMarkdown>
            <span className="streaming-cursor" />
          </>
        ) : liveThinking ? null : (
          // First token hasn't arrived yet — show an animated indicator
          // instead of a blank pane (the "no streaming" complaint).
          <div className="flex items-center gap-1.5 py-2 text-ink-faint">
            <Dots />
            <span className="ml-1.5 text-ui">正在生成…</span>
          </div>
        )
      ) : node.response ? (
        near ? (
          <>
            <MarkdownBody cacheKey={node.id} content={node.response} />
            <div className="mt-3 flex justify-end gap-2">
              <CliResumeButton nodeId={node.id} />
              <RegenerateVariantButton nodeId={node.id} question={node.question} />
              <CardImageButton
                title={node.topicLabel ?? node.question}
                content={node.response}
              />
              <CopyButton
                text={node.response}
                label="复制全文"
                className="nodrag px-2.5 py-1 rounded border border-line text-ui text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors"
              />
            </div>
            <GeneratedFilesBar node={node} />
          </>
        ) : (
          // 占位：成本约等于一个 text node。aria-hidden 避免屏幕阅读器念
          // 原始 markdown 符号；升级后真实内容自然可读。
          <div className="whitespace-pre-wrap break-words" aria-hidden>
            {node.response}
          </div>
        )
      ) : (
        <EmptyResponseNotice hasToolCalls={node.toolCalls.length > 0} />
      )}
      {isError && hasChildren && (
        <SupersededErrorNotice
          nodeId={node.id}
          errorMessage={node.errorMessage}
        />
      )}
      {isError &&
        !hasChildren &&
        (node.errorMessage === "aborted" ? (
          <div className="mt-3 p-2.5 bg-surface-muted border border-line rounded text-ink-muted text-ui flex items-start gap-2">
            <div className="flex-1">已停止生成</div>
            <Button
              variant="primary"
              size="sm"
              className="shrink-0"
              onClick={() => retryNode(node.id)}
            >
              ↻ 重新发送
            </Button>
          </div>
        ) : (
          <div className="mt-3 p-2.5 bg-danger-muted border border-danger-line rounded text-danger-ink text-ui flex items-start gap-2">
            <div className="flex-1">
              出错：{node.errorMessage}
              {isAuthErrorMessage(node.errorMessage) && (
                <a
                  href="/settings/models"
                  className="block mt-1 text-label underline underline-offset-2 opacity-80 hover:opacity-100"
                >
                  像是 CLI 授权问题 → 查看授权状态
                </a>
              )}
            </div>
            <Button
              variant="danger"
              size="sm"
              className="shrink-0"
              onClick={() => retryNode(node.id)}
            >
              ↻ 重新生成
            </Button>
          </div>
        ))}
    </div>
  );
}

function ReferenceFullBody({ node }: { node: ChatNode }) {
  const refreshReference = useSessionStore((s) => s.refreshReference);
  const abortStream = useSessionStore((s) => s.abortStream);
  const fetchProgress = useSessionStore((s) => s.fetchProgress[node.id]);
  const [refreshing, setRefreshing] = useState(false);
  const ref = node.reference;
  const isStreaming = node.status === "streaming";
  const bodyRef = useRef<HTMLDivElement>(null);
  const isAnchorTarget = useSessionStore(
    (s) => s.pendingScrollAnchor?.nodeId === node.id,
  );
  const near = useNearViewport(bodyRef, { force: isAnchorTarget });
  const { onMarkClick } = useMarkdownBodyMarks({
    bodyRef,
    nodeId: node.id,
    contentVersion: ref?.contentMd ?? "",
    suspended: isStreaming || !near,
  });
  if (!ref) {
    return (
      <div className="text-ink-faint italic text-sm">参考卡片数据缺失</div>
    );
  }
  const canRefresh = ref.sourceType === "url" && !isStreaming;
  const onRefresh = async () => {
    if (refreshing) return;
    setRefreshing(true);
    try {
      await refreshReference(node.id);
    } finally {
      setRefreshing(false);
    }
  };

  return (
    <>
      <div
        className={`mb-4 px-4 py-3 rounded-lg border text-ui flex items-start gap-2.5 ${
          isStreaming
            ? "bg-accent-muted border-accent-line"
            : "bg-warn-muted border-warn-line"
        }`}
      >
        <span className="text-title leading-none mt-0.5" aria-hidden>
          {isStreaming ? "⏳" : refIcon(ref)}
        </span>
        <div className="flex-1 min-w-0">
          <div className="font-semibold text-ink-strong truncate">
            {node.topicLabel ?? "参考材料"}
          </div>
          {ref.sourceUri && (
            <a
              href={ref.sourceUri}
              target="_blank"
              rel="noreferrer"
              className={`block mt-0.5 truncate underline-offset-2 hover:underline ${
                isStreaming ? "text-accent-ink" : "text-warn-ink"
              }`}
              onClick={(e) => e.stopPropagation()}
            >
              {ref.sourceUri}
            </a>
          )}
          {ref.meta.fetchError && !isStreaming && (
            <div className="mt-1 text-danger-ink text-ui">
              ⚠️ 抓取失败：{ref.meta.fetchError}
            </div>
          )}
        </div>
        {isStreaming ? (
          <StopButton
            label="停止"
            onClick={() => abortStream(node.id)}
            className="shrink-0"
            title="停止抓取"
          />
        ) : (
          canRefresh && (
            <button
              onClick={onRefresh}
              disabled={refreshing}
              className="shrink-0 px-2 py-1 text-label rounded border border-warn-line text-warn-ink hover:bg-warn-line/25 active:scale-95 disabled:opacity-50 transition-colors"
              title="重新抓取"
            >
              {refreshing ? "抓取中…" : "↻ 刷新"}
            </button>
          )
        )}
      </div>

      {isStreaming && (
        <div className="mb-4 px-4 py-3 rounded-lg bg-surface-muted border border-line">
          <div className="flex items-center gap-2 text-ui text-ink-muted">
            <span className="inline-block w-2 h-2 bg-accent rounded-full animate-pulse" />
            <span className="font-medium">{fetchProgress || "启动中…"}</span>
          </div>
          <div className="mt-2 text-label text-ink-faint leading-relaxed">
            claude 正在挑选并运行合适的 skill 抓取这个 URL。
            飞书 / YouTube / B站 等通常 5–60 秒，PDF / 大型文档可能更久。
            可以随时点上方"停止"取消。
          </div>
        </div>
      )}

      <div
        ref={bodyRef}
        data-chat-node-id={node.id}
        onClick={onMarkClick}
        className="md-body text-reading text-ink leading-relaxed"
      >
        {ref.contentMd ? (
          near ? (
            <MarkdownBody cacheKey={`ref:${node.id}`} content={ref.contentMd} />
          ) : (
            <div className="whitespace-pre-wrap break-words" aria-hidden>
              {ref.contentMd}
            </div>
          )
        ) : isStreaming ? null : (
          <div className="text-ink-faint italic text-sm">
            {ref.meta.fetchError
              ? "抓取失败，没有内容可显示。点上方刷新重试，或编辑后重新粘贴。"
              : "（没有正文）"}
          </div>
        )}
      </div>
    </>
  );
}

function truncate(s: string, n: number) {
  return s.length > n ? s.slice(0, n) + "…" : s;
}

"use client";
import { memo, useRef, useState, useEffect } from "react";
import {
  Handle,
  Position,
  useStore,
  type Node,
  type NodeProps,
} from "@xyflow/react";
import { useSessionStore } from "@/stores/sessionStore";
import {
  subscribeStream,
  getStreamPending,
  thinkingChannel,
} from "@/lib/stream-bus";
import { isAuthErrorMessage } from "@/lib/auth-error";
import { COMPACT_ZOOM_THRESHOLD, PEEK_CARD_HEIGHT } from "@/lib/layout";
import { MarkdownBody } from "@/lib/markdown-cache";
import { AttachmentPreview } from "./AttachmentPreview";
import { formatTokens } from "@/lib/format-tokens";
import { injectMarks, clearMarks, type MarkSpec } from "@/lib/dom-mark-injector";
import type { ChatNode as ChatNodeData, ToolCall } from "@/lib/types";
import {
  buildToolTree,
  countToolTree,
  subagentLabel,
  walkToolTree,
} from "@/lib/tool-tree";
import { CollapseChip } from "./CollapseChip";
import { DeleteCardButton } from "./DeleteCardButton";
import { SupersededErrorNotice } from "./SupersededErrorNotice";
import { CopyButton } from "./CopyButton";
import { isSendCombo, sendHint } from "@/lib/send-key";
import { useSkillSuggestions } from "@/hooks/useSkillSuggestions";
import { useSlashNav } from "@/hooks/useSlashNav";
import { SkillPickerList } from "./SkillPickerList";
import { ZoneEditor } from "./ZoneEditor";
import { EmptyResponseNotice } from "./EmptyResponseNotice";

export type ChildAnchor = { text: string; childId: string };

export type ChatFlowNode = Node<
  {
    node: ChatNodeData;
    isActive: boolean;
    childAnchors: ChildAnchor[];
    // 1-based session-scoped index (createdAt order). 0 if unknown.
    index: number;
    // Total descendants (direct + indirect). Drives the "▶/▼ N" chip;
    // 0 means the node is a leaf and the chip is suppressed.
    descendantCount: number;
    // Whether this node's subtree is currently folded.
    collapsed: boolean;
    // Peek: render this node's full card in place on the canvas (instead of
    // the compact topic card) without switching to the linear reader.
    isPeeked: boolean;
    onTogglePeek: (id: string) => void;
  },
  "chat"
>;

function ChatNodeImpl({ data }: NodeProps<ChatFlowNode>) {
  const n = data.node;
  const isStreaming = n.status === "streaming";
  const isError = n.status === "error";
  const isActive = data.isActive;
  const indexLabel = data.index ? `#${data.index}` : "";
  // Only "done" nodes can be unread — streaming / error states have their
  // own visual treatment (indigo border / error states).
  const isUnread = n.status === "done" && !n.readAt;
  // ReactFlow viewport zoom: transform = [x, y, zoom]. Selector returns a
  // boolean so re-renders only fire when crossing the threshold.
  const isCompact = useStore((s) => s.transform[2] < COMPACT_ZOOM_THRESHOLD);

  const setActiveNode = useSessionStore((s) => s.setActiveNode);
  const setViewMode = useSessionStore((s) => s.setViewMode);
  const retryNode = useSessionStore((s) => s.retryNode);
  const toggleCollapse = useSessionStore((s) => s.toggleCollapse);
  const showCollapseChip = data.descendantCount > 0;
  const onMarkClick = (e: React.MouseEvent) => {
    const target = (e.target as HTMLElement).closest("[data-child-id]");
    if (!target) return;
    const childId = target.getAttribute("data-child-id");
    if (!childId) return;
    e.preventDefault();
    e.stopPropagation();
    e.nativeEvent.stopImmediatePropagation();
    // ReactFlow's onNodeClick fires on the same click and would override
    // activeNodeId to the parent's id. Defer to win the race.
    window.setTimeout(() => setActiveNode(childId), 0);
  };
  // #7: reading happens in the linear thread anchored at this node (the old
  // fullscreen single-card reader is retired).
  const goRead = (e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveNode(n.id);
    setViewMode("linear");
  };
  // While streaming, deltas land on the stream-bus (not in React state).
  // We attach a textContent-only sink to a <pre> ref so each token is one
  // tiny DOM mutation, no React render, no ReactFlow diff. When the stream
  // finishes, sessionStore commits the full text and React re-renders this
  // node once with the full ReactMarkdown pipeline.
  const streamRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!isStreaming) return;
    const el = streamRef.current;
    if (!el) return;
    el.textContent = n.response + getStreamPending(n.id);
    return subscribeStream(n.id, (delta) => {
      el.textContent = (el.textContent ?? "") + delta;
    });
    // n.response intentionally excluded from deps: it doesn't change while
    // streaming (deltas bypass the store), and re-running this effect on
    // every render would clobber the DOM-direct text.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isStreaming, n.id]);

  // Extended thinking indicator: claude thinks BEFORE it answers (minutes
  // under high effort), during which streamRef stays empty and the card used
  // to look dead. DOM-direct toggle (same no-React-render discipline as
  // streamRef): visible while thinking deltas flow and no text has arrived.
  const thinkingRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!isStreaming) return;
    const el = thinkingRef.current;
    if (!el) return;
    const sync = () => {
      const hasText =
        n.response.length > 0 || getStreamPending(n.id).length > 0;
      const hasThinking = getStreamPending(thinkingChannel(n.id)).length > 0;
      el.style.display = hasThinking && !hasText ? "flex" : "none";
    };
    sync();
    const unsubThinking = subscribeStream(thinkingChannel(n.id), sync);
    const unsubText = subscribeStream(n.id, sync);
    return () => {
      unsubThinking();
      unsubText();
    };
    // n.response excluded for the same reason as the effect above.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isStreaming, n.id]);

  // Inject child <mark> on the rendered markdown DOM. Same approach as
  // NodeFullView's ResponseBody — see lib/dom-mark-injector.ts.
  const bodyRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (isStreaming) return;
    const root = bodyRef.current;
    if (!root) return;
    clearMarks(root);
    if (data.childAnchors.length) {
      const specs: MarkSpec[] = [
        {
          dataKey: "childId",
          anchors: data.childAnchors.map((a) => ({
            text: a.text,
            id: a.childId,
          })),
        },
      ];
      injectMarks(root, specs);
    }
    return () => {
      if (root) clearMarks(root);
    };
  }, [isStreaming, n.response, data.childAnchors]);

  const labelText = n.topicLabel ?? truncate(n.question, 14);
  // 错误降级：有后代 = 用户已在后续节点续跑/绕过，错误不再是"待处理"状态。
  const errorSuperseded = isError && data.descendantCount > 0;
  // Compact mode: streaming / fresh-error nodes always render full so user
  // can see progress and act. Done nodes — and superseded errors, whose
  // loud treatment has expired — collapse to a topic card at low zoom.
  const showCompact =
    isCompact &&
    !isStreaming &&
    (!isError || errorSuperseded) &&
    !data.isPeeked;

  if (showCompact) {
    return (
      <div
        className={`group relative nopan w-[280px] rounded-card bg-surface cursor-pointer transition-all duration-200 ring-1 shadow-[0_1px_2px_rgba(28,25,23,0.04),0_6px_20px_-6px_rgba(28,25,23,0.10)] hover:shadow-[0_2px_4px_rgba(28,25,23,0.05),0_14px_30px_-8px_rgba(28,25,23,0.18)] hover:-translate-y-px ${
          isActive
            ? "ring-2 ring-accent/80"
            : isUnread
              ? "ring-unread-line/80"
              : "ring-line/80 hover:ring-line-strong"
        }`}
        onClick={goRead}
        title={n.question}
      >
        <Handle type="target" position={Position.Top} />
        <DeleteCardButton nodeId={n.id} />
        {/* Peek toggle: a hover-only corner chip matching DeleteCardButton's
            circle, parked just left of the ✕ — same visual language, no
            content-row clutter. */}
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            data.onTogglePeek(n.id);
          }}
          title="展开预览（留在画布）"
          aria-label="展开预览"
          className="absolute -top-2 right-4 z-10 w-5 h-5 rounded-full border bg-surface border-line-strong text-ink-muted shadow-raise opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 hover:bg-ink hover:text-ink-inverse hover:border-ink transition-opacity flex items-center justify-center"
        >
          <svg
            width="10"
            height="10"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2.6"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden
          >
            <path d="M6 9l6 6 6-6" />
          </svg>
        </button>
        {showCollapseChip && (
          <CollapseChip
            collapsed={data.collapsed}
            count={data.descendantCount}
            onClick={(e) => {
              e.stopPropagation();
              toggleCollapse(n.id);
            }}
            variant="compact"
          />
        )}
        <span
          className={`absolute left-0 top-3 bottom-3 w-[3px] rounded-r-full ${
            isError
              ? "bg-warn"
              : n.status !== "done"
                ? "bg-line-strong"
                : isUnread
                  ? "bg-unread"
                  : "bg-line-strong/70"
          }`}
          aria-hidden
          title={n.status === "done" ? (isUnread ? "未读" : "已读") : undefined}
        />
        <div className="px-4 py-3 flex items-center gap-2.5">
          {indexLabel && (
            <span className="shrink-0 text-label font-mono text-ink-faint tabular-nums">
              {indexLabel}
            </span>
          )}
          <div className="flex-1 min-w-0">
            <div className="text-title font-semibold text-ink-strong leading-tight truncate">
              {labelText}
            </div>
            {n.parentAnchor && (
              <div className="mt-0.5 text-label text-fork-ink truncate">
                ↳ {truncate(n.parentAnchor.selectedText, 22)}
              </div>
            )}
          </div>
          {n.pendingInteraction && (
            <span
              className="shrink-0 px-1.5 py-0.5 rounded-full bg-warn-muted text-warn-ink text-nano font-medium"
              title="待你回答"
            >
              🙋
            </span>
          )}
          {isError && (
            <span
              className="shrink-0 text-warn-ink text-nano"
              title={
                n.errorMessage === "aborted"
                  ? "本轮已手动停止（后续已继续）"
                  : `本轮中途中断（后续已继续）：${n.errorMessage ?? ""}`
              }
            >
              ⚠
            </span>
          )}
          <ToolCallBadge toolCalls={n.toolCalls} />
          <TokenMeta tokenCount={n.tokenCount} variant="compact" />
        </div>
        <Handle type="source" position={Position.Bottom} />
      </div>
    );
  }

  return (
    <div
      // When shown because of peek, pin to a fixed height and let the body
      // flex-fill + scroll inside — so the card's on-canvas footprint is a
      // known constant the layout can reserve exactly (see PEEK_CARD_HEIGHT).
      style={data.isPeeked ? { height: PEEK_CARD_HEIGHT } : undefined}
      className={`group relative nopan bg-surface border rounded-card shadow-raise w-[600px] transition-all ${
        data.isPeeked ? "flex flex-col" : ""
      } ${
        isStreaming
          ? "border-accent-line ring-4 ring-accent-muted"
          : isActive
            ? "border-accent ring-2 ring-accent-line/60 shadow-raise"
            : isUnread
              ? "border-unread-line"
              : "border-line"
      }`}
    >
      <Handle type="target" position={Position.Top} />
      <DeleteCardButton nodeId={n.id} />
      {showCollapseChip && (
        <CollapseChip
          collapsed={data.collapsed}
          count={data.descendantCount}
          onClick={(e) => {
            e.stopPropagation();
            toggleCollapse(n.id);
          }}
          variant="full"
        />
      )}

      {n.parentAnchor && (
        <div className="px-4 py-2 border-b border-line-faint bg-fork-muted text-label text-fork-ink flex items-center gap-1.5 rounded-t-card">
          <span className="text-fork">↳</span>
          <span>
            从「
            <span className="font-medium">
              {truncate(n.parentAnchor.selectedText, 40)}
            </span>
            」分叉
          </span>
        </div>
      )}

      {n.pendingInteraction && (
        <div
          className={`px-4 py-1.5 border-b border-warn-line bg-warn-muted text-label font-medium text-warn-ink flex items-center gap-1.5 ${
            n.parentAnchor ? "" : "rounded-t-card"
          }`}
        >
          <span>🙋</span>
          <span>待你回答</span>
        </div>
      )}

      <div
        className={`px-5 py-3 border-b border-line-faint flex items-start gap-2.5 ${
          n.parentAnchor || n.pendingInteraction
            ? ""
            : "bg-accent-muted/60 rounded-t-card"
        }`}
      >
        <div className="w-7 h-7 rounded-full bg-accent text-ink-inverse text-label flex items-center justify-center mt-0.5 shrink-0 font-medium">
          你
        </div>
        <div
          className={`flex-1 text-body text-ink leading-relaxed pt-1 font-medium min-w-0 ${
            // Peek pins the whole card to PEEK_CARD_HEIGHT with the body as the
            // flex-fill scroll area. A long question / many attachments would
            // otherwise grow this header unbounded, pushing the card past its
            // reserved footprint and over the child below — so cap + scroll it.
            data.isPeeked ? "max-h-[200px] overflow-y-auto" : ""
          }`}
        >
          {indexLabel && (
            <span className="mr-1.5 font-mono text-ui text-ink-faint tabular-nums font-normal inline-flex items-center gap-1">
              {indexLabel}
              {isUnread && (
                <span
                  className="w-1.5 h-1.5 rounded-full bg-unread"
                  aria-label="未读"
                  title="未读"
                />
              )}
            </span>
          )}
          {n.question}
          {n.attachments.length > 0 && (
            <div className="mt-2 font-normal">
              <AttachmentPreview attachments={n.attachments} readOnly />
            </div>
          )}
        </div>
        {data.isPeeked && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              data.onTogglePeek(n.id);
            }}
            title="收起预览"
            aria-label="收起预览"
            className="shrink-0 mt-0.5 px-2 h-7 rounded-md bg-surface border border-line-strong text-ink-muted hover:bg-ink hover:text-ink-inverse hover:border-ink active:scale-95 flex items-center gap-1 text-label font-medium transition-colors shadow-raise"
          >
            <svg
              width="13"
              height="13"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.2"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden
            >
              <path d="M18 15l-6-6-6 6" />
            </svg>
            收起
          </button>
        )}
        <button
          onClick={goRead}
          title="线性阅读"
          aria-label="线性阅读"
          className="shrink-0 mt-0.5 px-2 h-7 rounded-md bg-surface border border-line-strong text-ink-muted hover:bg-ink hover:text-ink-inverse hover:border-ink active:scale-95 flex items-center gap-1 text-label font-medium transition-colors shadow-raise"
        >
          <svg
            width="13"
            height="13"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2.2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
          </svg>
          阅读
        </button>
      </div>

      <div
        ref={bodyRef}
        data-chat-node-id={n.id}
        onClick={onMarkClick}
        className={`px-5 py-4 md-body text-body text-ink-muted overflow-y-auto nodrag nowheel nopan ${
          data.isPeeked ? "flex-1 min-h-0" : "max-h-[420px]"
        }`}
      >
        {isStreaming ? (
          <>
            <div
              ref={thinkingRef}
              style={{ display: "none" }}
              className="items-center gap-1.5 mb-1 text-ui text-ink-faint"
            >
              <span className="w-1.5 h-1.5 rounded-full bg-accent animate-pulse" />
              思考中…
            </div>
            <div
              ref={streamRef}
              className="whitespace-pre-wrap break-words leading-relaxed"
            />
            <span className="streaming-cursor" />
          </>
        ) : n.response ? (
          <MarkdownBody cacheKey={n.id} content={n.response} />
        ) : (
          <EmptyResponseNotice hasToolCalls={(n.toolCalls?.length ?? 0) > 0} />
        )}
        {errorSuperseded && (
          <SupersededErrorNotice nodeId={n.id} errorMessage={n.errorMessage} />
        )}
        {isError &&
          !errorSuperseded &&
          (n.errorMessage === "aborted" ? (
            <div className="mt-3 p-2 bg-surface-muted border border-line rounded text-ink-muted text-xs flex items-start gap-2">
              <div className="flex-1">已停止生成</div>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  retryNode(n.id);
                }}
                className="shrink-0 px-2 py-0.5 rounded bg-accent text-ink-inverse text-label hover:bg-accent-strong active:scale-95 transition-transform"
              >
                ↻ 重新发送
              </button>
            </div>
          ) : (
            <div className="mt-3 p-2 bg-danger-muted border border-danger-line rounded text-danger-ink text-xs flex items-start gap-2">
              <div className="flex-1">
                出错：{n.errorMessage}
                {isAuthErrorMessage(n.errorMessage) && (
                  <a
                    href="/settings/models"
                    onClick={(e) => e.stopPropagation()}
                    className="block mt-1 underline underline-offset-2 opacity-80 hover:opacity-100"
                  >
                    像是 CLI 授权问题 → 查看授权状态
                  </a>
                )}
              </div>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  retryNode(n.id);
                }}
                className="shrink-0 px-2 py-0.5 rounded bg-danger text-ink-inverse text-label hover:bg-danger-strong active:scale-95 transition-transform"
              >
                ↻ 重新生成
              </button>
            </div>
          ))}
      </div>

      <NodeFooter node={n} isStreaming={isStreaming} />

      <Handle type="source" position={Position.Bottom} />
    </div>
  );
}

// React.memo with custom comparison so streaming a single node doesn't
// re-render every other node on every token. Hot path: handleStreamEvent
// in sessionStore preserves identity for non-streaming nodes (only the
// streaming node's object is replaced), so `prev.node === next.node`
// catches them. childAnchors is rebuilt by the Canvas selector on every
// nodeMap change but is small per-parent — value-compare it.
export const ChatNode = memo(ChatNodeImpl, (prev, next) => {
  if (prev.data.node !== next.data.node) return false;
  if (prev.data.isActive !== next.data.isActive) return false;
  if (prev.data.collapsed !== next.data.collapsed) return false;
  if (prev.data.isPeeked !== next.data.isPeeked) return false;
  if (prev.data.descendantCount !== next.data.descendantCount) return false;
  const a = prev.data.childAnchors;
  const b = next.data.childAnchors;
  if (a !== b) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (a[i].childId !== b[i].childId || a[i].text !== b[i].text) return false;
    }
  }
  return true;
});

function NodeFooter({
  node,
  isStreaming,
}: {
  node: ChatNodeData;
  isStreaming: boolean;
}) {
  const [open, setOpen] = useState(false);
  const abortStream = useSessionStore((s) => s.abortStream);

  if (open) {
    return <FollowupInput node={node} onClose={() => setOpen(false)} />;
  }

  return (
    <div className="px-5 py-2 border-t border-line-faint flex items-center gap-2 text-xs text-ink-muted">
      {isStreaming ? (
        <>
          <span className="w-1.5 h-1.5 bg-positive rounded-full animate-pulse" />
          <span>正在生成…</span>
          <button
            onClick={(e) => {
              e.stopPropagation();
              abortStream(node.id);
            }}
            className="ml-2 px-2 py-0.5 rounded border border-line-strong bg-surface text-ink-muted hover:bg-ink hover:text-ink-inverse hover:border-ink active:scale-95 transition-colors flex items-center gap-1"
            title="停止生成 (Esc)"
            aria-label="停止生成"
          >
            <span className="inline-block w-2 h-2 bg-current rounded-[1px]" />
            停止
          </button>
        </>
      ) : (
        <>
          <ToolCallBadge toolCalls={node.toolCalls} />
          <TokenMeta tokenCount={node.tokenCount} variant="full" />
          {node.response && (
            <CopyButton
              text={node.response}
              className="nodrag ml-2 px-2 py-0.5 rounded text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors"
            />
          )}
          <button
            onClick={() => setOpen(true)}
            className="ml-1 px-2 py-0.5 rounded text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors"
          >
            + 追问
          </button>
        </>
      )}
      <span className="ml-auto text-ink-faint italic text-label">
        或选中文字 → ⌘K 提问
      </span>
    </div>
  );
}

function FollowupInput({
  node,
  onClose,
}: {
  node: ChatNodeData;
  onClose: () => void;
}) {
  const [q, setQ] = useState("");
  const [zoneOpen, setZoneOpen] = useState(false);
  const ref = useRef<HTMLTextAreaElement>(null);
  const streamBranch = useSessionStore((s) => s.streamBranch);
  const sendKey = useSessionStore((s) => s.sendKey);
  const sessionMode = useSessionStore((s) => s.session?.mode);
  const chatEnhanced = useSessionStore((s) => s.chatEnhanced);
  const setChatEnhanced = useSessionStore((s) => s.setChatEnhanced);
  // Skills show in every mode; picking one in pure chat auto-enables 增强模式
  // (per-turn spawn flag — Header badge reflects it) so the skill can run.
  const matchedSkills = useSkillSuggestions(q, true);
  const pickSkill = (name: string) => {
    if (sessionMode === "chat" && !chatEnhanced) setChatEnhanced(true);
    setQ(`/${name} `);
    ref.current?.focus();
  };
  const slashNav = useSlashNav(matchedSkills.length, q, (i) =>
    pickSkill(matchedSkills[i].name),
  );

  useEffect(() => {
    ref.current?.focus();
  }, []);

  const submit = async () => {
    const text = q.trim();
    if (!text) return;
    onClose();
    streamBranch(node.id, text, null);
  };

  return (
    <div className="relative border-t border-line-faint bg-surface-canvas/60">
      <SkillPickerList
        skills={matchedSkills}
        onPick={pickSkill}
        activeIndex={slashNav.active}
      />
      {/* px-1.5 insets the full-width textarea so its :focus-visible outline
          (globals.css — 2px solid + 2px offset, a non-layered rule utilities
          can't override) stays inside the card border instead of poking past
          it. */}
      <div className="px-1.5">
        <textarea
          ref={ref}
          value={q}
          onChange={(e) => setQ(e.target.value)}
          onKeyDown={(e) => {
            if (slashNav.handleKeyDown(e)) return;
            if (isSendCombo(e, sendKey)) {
              e.preventDefault();
              submit();
            } else if (e.key === "Escape") {
              e.preventDefault();
              onClose();
            }
          }}
          placeholder={`对整段回复继续追问…（${sendHint(sendKey)}）`}
          rows={2}
          className="w-full px-3.5 py-3 outline-none resize-none text-sm bg-transparent text-ink placeholder:text-ink-faint"
        />
      </div>
      <div className="px-3 py-1.5 flex items-center justify-end gap-2 text-xs">
        <button
          onClick={() => setZoneOpen(true)}
          title="专注写作模式（全屏 Markdown 编辑 + 预览）"
          className="mr-auto px-2 py-0.5 text-ink-muted hover:text-ink-strong inline-flex items-center gap-1"
        >
          <span aria-hidden>⛶</span>
          <span>专注写作</span>
        </button>
        <button
          onClick={onClose}
          className="px-2 py-0.5 text-ink-muted hover:text-ink-strong"
        >
          取消
        </button>
        <button
          onClick={submit}
          disabled={!q.trim()}
          className="px-2.5 py-0.5 rounded bg-accent text-ink-inverse disabled:opacity-40 hover:bg-accent-strong"
        >
          提问
        </button>
      </div>
      {zoneOpen && (
        <ZoneEditor
          value={q}
          onChange={setQ}
          onSubmit={() => {
            if (!q.trim()) return;
            setZoneOpen(false);
            submit();
          }}
          onClose={() => setZoneOpen(false)}
          title="继续追问"
          placeholder="专注写下你的追问，支持 Markdown……"
          submitLabel="提问"
          submitDisabled={!q.trim()}
        />
      )}
    </div>
  );
}

function truncate(s: string, n: number) {
  return s.length > n ? s.slice(0, n) + "…" : s;
}

// Inline token meter shared by the compact-card right side and the
// Stage 17: small badge that surfaces tool-call count on the canvas
// card + fullscreen footer. Hidden when count is 0 so chat-mode nodes
// (which rarely invoke tools) don't grow extra clutter. Click is
// non-interactive — drill-down lives in the timeline inside the
// fullscreen view.
//
// 🔧 is every call in the turn; delegation gets its own 🤖 / ⚙ count so a turn
// that fanned out reads as such at a glance instead of just showing an
// inflated tool number.
function ToolCallBadge({ toolCalls }: { toolCalls: ToolCall[] }) {
  const tree = buildToolTree(toolCalls);
  const counts = countToolTree(tree);
  if (counts.total === 0) return null;
  const labels = walkToolTree(tree)
    .filter((n) => n.kind === "subagent")
    .map((n) => subagentLabel(n.meta));
  return (
    <span className="shrink-0 inline-flex items-center gap-1 text-nano tabular-nums text-ink-muted">
      <span title={`本轮共 ${counts.total} 次工具调用`}>🔧{counts.total}</span>
      {counts.subagents > 0 && (
        <span title={`派了 ${counts.subagents} 个子 Agent：${labels.join("、")}`}>
          🤖{counts.subagents}
        </span>
      )}
      {counts.workflows > 0 && (
        <span title={`跑了 ${counts.workflows} 个 Workflow`}>
          ⚙{counts.workflows}
        </span>
      )}
    </span>
  );
}

// fullscreen footer. Three buckets (↑ in, ↓ out, ⚡ cache hit). cache
// creation is collapsed into the cache slot only when non-zero (rare —
// happens on first cli-multi turn) by appending +N. We deliberately
// omit fields that are zero to keep idle nodes uncluttered.
function TokenMeta({
  tokenCount,
  variant,
}: {
  tokenCount: ChatNodeData["tokenCount"];
  variant: "compact" | "full";
}) {
  const { input, output, cacheRead, cacheCreation } = tokenCount;
  const hasAny =
    input > 0 || output > 0 || cacheRead > 0 || cacheCreation > 0;
  if (!hasAny) {
    return (
      <span
        className={
          variant === "compact"
            ? "shrink-0 text-nano text-ink-faint tabular-nums"
            : "text-ink-faint tabular-nums"
        }
      >
        —
      </span>
    );
  }
  const baseCls = "tabular-nums whitespace-nowrap";
  const sizeCls = variant === "compact" ? "text-nano" : "text-label";
  return (
    <span
      className={`shrink-0 inline-flex items-center gap-1.5 ${sizeCls} ${baseCls} text-ink-muted`}
      title={`输入 ${input} · 输出 ${output} · 缓存命中 ${cacheRead}${
        cacheCreation > 0 ? ` · 缓存写入 ${cacheCreation}` : ""
      }`}
    >
      <span>↑{formatTokens(input)}</span>
      <span>↓{formatTokens(output)}</span>
      {(cacheRead > 0 || cacheCreation > 0) && (
        <span className="text-positive">
          ⚡{formatTokens(cacheRead)}
          {cacheCreation > 0 ? `+${formatTokens(cacheCreation)}` : ""}
        </span>
      )}
    </span>
  );
}

