  const SID = '37f1e158-bfe2-4564-b49a-45767900d964';
  const MARKER = '2d43d9de-50a9-475e-b956-f8e5bdd561ca';
  const longtasks = [];
  try {
    new PerformanceObserver((list) => {
      for (const e of list.getEntries()) longtasks.push({start: Math.round(e.startTime), dur: Math.round(e.duration)});
    }).observe({ entryTypes: ['longtask'] });
  } catch(e) {}
  const t0 = performance.now();
  const span = [...document.querySelectorAll('span')].find(e => e.textContent.trim() === '怎么访问我的 boe 机器');
  if (!span) return resolve({error: 'span not found'});
  span.click();
  let markerAt = 0, settledAt = 0, lastCount = -1, stableSince = 0;
  const iv = setInterval(() => {
    const now = performance.now() - t0;
    const marker = document.querySelector('.react-flow__node[data-id=\"' + MARKER + '\"]');
    if (marker && !markerAt) markerAt = now;
    const count = document.querySelectorAll('.react-flow__node').length;
    if (count !== lastCount) { lastCount = count; stableSince = now; }
    if (markerAt && now - stableSince > 400 && now > 800) {
      clearInterval(iv);
      const res = performance.getEntriesByType('resource').filter(e => e.name.includes('/api/sessions/' + SID));
      resolve({
        totalMs: Math.round(now),
        markerAppearedMs: Math.round(markerAt),
        finalNodeCount: count,
        fetch: res.map(e => ({
          ttfbMs: Math.round(e.responseStart - e.startTime),
          downloadMs: Math.round(e.responseEnd - e.responseStart),
          totalMs: Math.round(e.responseEnd - e.startTime),
          encodedKB: Math.round((e.encodedBodySize || 0)/1024),
          decodedKB: Math.round((e.decodedBodySize || 0)/1024),
          compressed: e.encodedBodySize > 0 && e.encodedBodySize < e.decodedBodySize,
        })),
        longtasks: longtasks,
        longtaskTotalMs: longtasks.reduce((s,e)=>s+e.dur,0),
      });
    }
    if (now > 15000) { clearInterval(iv); resolve({error: 'timeout', markerAt, count, longtasks}); }
  }, 50);
});
