(() => {
  // find the sidebar row containing issue-55
  const rows = [...document.querySelectorAll('[onclick], button, div')].filter(e => {
    const r = e.getBoundingClientRect();
    return r.width > 50 && r.y > 100 && r.y < 400 && e.textContent.trim().startsWith('issue-55') && e.textContent.trim().length < 60;
  });
  if (!rows.length) return 'no row';
  const row = rows[rows.length-1];
  row.click();
