import { getSession, getSessionNodes } from "./lib/server/repo";
import {
  buildToolTree,
  countToolTree,
  subagentLabel,
  walkToolTree,
} from "./lib/tool-tree";
import { generatedFilesFromToolCalls } from "./lib/generated-files";

const id = "37f1e158-bfe2-4564-b49a-45767900d964";
const session = getSession(id);
if (!session) throw new Error("no session");
const nodes = getSessionNodes(id);

// Old payload (full toolCalls)
const oldPayload = JSON.stringify({ session, nodes, notes: [] });

// New payload (slim)
const slimNodes = nodes.map((n) => {
  const tree = buildToolTree(n.toolCalls);
  const counts = countToolTree(tree);
  const labels = walkToolTree(tree)
    .filter((t) => t.kind === "subagent")
    .map((t) => subagentLabel(t.meta));
  const { toolCalls: _omit, ...rest } = n;
  return {
    ...rest,
    toolCallStats: {
      total: counts.total,
      subagents: counts.subagents,
      workflows: counts.workflows,
      errors: counts.errors,
      labels,
    },
    generatedFiles: generatedFilesFromToolCalls(n.toolCalls),
  };
});
const newPayload = JSON.stringify({ session, nodes: slimNodes, notes: [] });

const fmt = (n: number) => (n / 1024 / 1024).toFixed(2) + " MB";
console.log("nodes:", nodes.length);
console.log("old payload:", fmt(oldPayload.length), `(${oldPayload.length} bytes)`);
console.log("new payload:", fmt(newPayload.length), `(${newPayload.length} bytes)`);
console.log("reduction:", (100 * (1 - newPayload.length / oldPayload.length)).toFixed(1) + "%");
// gzip estimate
const oldGz = Bun.gzipSync(oldPayload).length;
const newGz = Bun.gzipSync(newPayload).length;
console.log("old gzip:", fmt(oldGz), " new gzip:", fmt(newGz));
// per-node toolCalls size sanity
let tcBytes = 0;
for (const n of nodes) tcBytes += JSON.stringify(n.toolCalls).length;
console.log("toolCalls total:", fmt(tcBytes));

