import { Database } from "bun:sqlite";
import {
  buildToolTree,
  countToolTree,
  subagentLabel,
  walkToolTree,
} from "@/lib/tool-tree";
import { generatedFilesFromToolCalls } from "@/lib/generated-files";

const db = new Database("/data00/home/zhangpeng.pada/.trellis/data.db", {
  readonly: true,
});
const id = "37f1e158-bfe2-4564-b49a-45767900d964";
const rows = db
  .query("SELECT id, tool_calls_json FROM nodes WHERE session_id = ?")
  .all(id) as { id: string; tool_calls_json: string | null }[];

let oldBytes = 0;
let newBytes = 0;
let tcBytes = 0;
let statsBytes = 0;
let genBytes = 0;
for (const r of rows) {
  const toolCalls = r.tool_calls_json ? JSON.parse(r.tool_calls_json) : [];
  const tree = buildToolTree(toolCalls);
  const counts = countToolTree(tree);
  const labels = walkToolTree(tree)
    .filter((t) => t.kind === "subagent")
    .map((t) => subagentLabel(t.meta));
  const stats = {
    total: counts.total,
    subagents: counts.subagents,
    workflows: counts.workflows,
    errors: counts.errors,
    labels,
  };
  const generated = generatedFilesFromToolCalls(toolCalls);
  tcBytes += JSON.stringify(toolCalls).length;
  statsBytes += JSON.stringify(stats).length;
  genBytes += JSON.stringify(generated).length;
}
// old payload ≈ everything + toolCalls; new ≈ everything - toolCalls + stats + gen
// We only measure the toolCalls-related delta precisely; the rest is constant.
const rest = 0; // constant between the two
oldBytes = tcBytes;
newBytes = statsBytes + genBytes;
const fmt = (n: number) => (n / 1024 / 1024).toFixed(2) + " MB";
console.log("nodes:", rows.length);
console.log("toolCalls total:", fmt(tcBytes), `(${tcBytes} B)`);
console.log("stats total:", fmt(statsBytes), `(${statsBytes} B)`);
console.log("generatedFiles total:", fmt(genBytes), `(${genBytes} B)`);
console.log("---");
console.log("toolCalls portion — old:", fmt(oldBytes), " new:", fmt(newBytes));
console.log(
  "toolCalls portion reduction:",
  (100 * (1 - newBytes / oldBytes)).toFixed(1) + "%",
);

